@Entity
@Table(name = "accounts")
@Cacheable
@org.hibernate.annotations.Cache(usage = org.hibernate.annotations.CacheConcurrencyStrategy.READ_WRITE)
public class Account {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String owner;

    @Column(nullable = false)
    private BigDecimal balance;

    // getters, setters, constructors
}

@Service
public class AccountService {

    @PersistenceContext
    private EntityManager em;

    @Transactional
    public void demonstrateCaches(Long accountId) {
        // Hits database, stores in First-level cache (PersistenceContext) and L2C
        Account a1 = em.find(Account.class, accountId);

        // Hits First-level cache directly; zero SQL generated
        Account a2 = em.find(Account.class, accountId);

        // true - same memory reference in the same PersistenceContext
        boolean isSameReference = (a1 == a2);
    }
}
